Path('outputs/ROMDex/tests/building-hierarchy.test.mjs').write_text('''import test from 'node:test';import assert from 'node:assert/strict';
import {fixture} from './rom-compilation-fixture.mjs';import {compileMapExtraction} from '../rom/compile-map.mjs';import {upgradeBuildingHierarchy} from '../rom/building-hierarchy.mjs';import {prepareGroupedDocument} from '../rom/grouped-document.mjs';import {mapDomain,previewMapImport} from '../rdx/map-import.mjs';import {documentRevision} from '../rdx/document.mjs';import {canonical,seal} from '../content/contracts.mjs';import {packRdx,unpackRdx} from '../rdx/container.mjs';
// Fictional content exercises the hierarchy adapter, not real-ROM extraction.
async function source(header=61){const f=fixture(),v=await compileMapExtraction(f.x,f.assets,f.inventory),document=structuredClone(v.document);document.content.records=document.content.records.map(r=>r.kind==='subzone'?seal({...r,current:{...r.current,payload:{...r.current.payload,name:'T20R0101'}},legacyData:{...r.legacyData,romExtraction:{...r.legacyData.romExtraction,headerId:header}}}):r);document.content.recordHeads=document.content.records.map(r=>({recordId:r.recordId,revisionId:r.revisionId}));document.revision=documentRevision(document);return {...v,document,documentBytes:Buffer.from(canonical(document))};}
test('building upgrade preserves every physical identity, source mapping and payload, and is portable and idempotent',async()=>{const before=await source(),next=upgradeBuildingHierarchy(before),a=mapDomain(before),b=mapDomain(next),building=b.records.find(r=>r.legacyData.romBuilding);assert.equal(building.current.payload.name,"Elm's Lab");for(const r of a.records){const n=b.records.find(n=>n.recordId===r.recordId);assert(n);if(r.kind!=='map')assert.deepEqual(n.current,r.current);assert.deepEqual(n.mappingRefs,r.mappingRefs);}assert.equal(b.records.find(r=>r.kind==='subzone'&&!r.legacyData.romBuilding).parentRecordId,building.recordId);assert.equal(upgradeBuildingHierarchy(next),next);const portable=await unpackRdx(await packRdx(next.documentBytes,next.blobs));assert.equal(portable.document.revision,next.document.revision);assert.equal(previewMapImport(next,before).preview.conflicts.length,0);});
test('unknown or mismatched source-area identities never acquire an inferred building',async()=>{const before=await source(999);assert.equal(upgradeBuildingHierarchy(before),before);});
test('repreparation retains logical building parents and their original child identities',async()=>{const before=await source(),next=upgradeBuildingHierarchy(before),map=mapDomain(next).records.find(r=>r.kind==='map'),merged=prepareGroupedDocument(before,next,{rootId:'fixture-root',nodes:[{id:'fixture-root',name:'Fictional map',parentId:null,ownHeaders:[61]}]}),a=mapDomain(next),b=mapDomain(merged);assert.equal(b.records.find(r=>r.kind==='map').recordId,map.recordId);for(const r of a.records.filter(r=>r.kind==='subzone')){const n=b.records.find(n=>n.recordId===r.recordId);assert(n);assert.equal(n.parentRecordId,r.parentRecordId);assert.deepEqual(n.current,r.current);}});
''',encoding='utf-8',newline='\n')
